package io.github.diodeme.ji.host;

import java.util.List;
import java.util.Optional;

/** Atomic Host command journal, durable delivery, and snapshot port. */
public interface HostStore {
    Commit commit(String sessionId, String commandId, String payloadHash, String resultRef,
                  String eventType, byte[] eventPayload, long expectedSessionRevision);
    Optional<Commit> command(String sessionId, String commandId, String payloadHash);
    Snapshot snapshot(String sessionId);
    List<DurableEvent> replay(String sessionId, long afterEventSeq);

    record Commit(long acceptedSeq, long eventSeq, long snapshotRevision, String resultRef) {}
    record DurableEvent(long eventSeq, long snapshotRevision, String eventType, byte[] payload) {
        public DurableEvent { payload = payload.clone(); }
        @Override public byte[] payload() { return payload.clone(); }
    }
    record Snapshot(long revision, long baseEventSeq, byte[] payload) {
        public Snapshot { payload = payload.clone(); }
        @Override public byte[] payload() { return payload.clone(); }
    }
}
